-- Ensure values and meanings arrays have matching lengths
DO $$ BEGIN
  ALTER TABLE coordinate_mappings
  ADD CONSTRAINT values_meanings_length_match
  CHECK (jsonb_array_length(option_values) = jsonb_array_length(option_meanings));
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

-- RLS: public read, service role write
